INSERT INTO jobs (id, sort_order, years, period, title, company, company_tip_title, company_tip_body, summary, highlights_json, details_json) VALUES ('job-phl', 1, '2025–2026', 'Th4/2025 – Th3/2026', 'Senior Content Marketing', 'Phú Hưng Life', 'Phú Hưng Life', 'Doanh nghiệp bảo hiểm nhân thọ với mạng lưới văn phòng trên toàn quốc.', 'Giữ giọng nói thương hiệu cho một doanh nghiệp bảo hiểm trên mọi kênh, từ báo chí đến nội bộ.', '["Chiến dịch PR ra mắt Tổng Giám đốc mới trên VnExpress, Dân Trí, Tuổi Trẻ, Vietcetera.","Tăng 30% tương tác tổng trên Website, Facebook, LinkedIn và TikTok.","Kiểm soát nhận diện tại mọi văn phòng toàn quốc, tuân thủ 100% brand guideline."]', '["Viết bài phát biểu, kịch bản và thông điệp chiến lược hằng tháng cho Tổng Giám đốc.","Xử lý truyền thông trong các tình huống khủng hoảng nhạy cảm.","Thiết kế và vận hành truyền thông nội bộ trên Email, GapoWork, Facebook Group.","Sản xuất thiết kế và video cho social và chiến dịch doanh nghiệp.","Đồng tổ chức chuỗi CSR giáo dục tài chính cho phụ nữ Vĩnh Long: 10 buổi trong 6 tháng, hơn 1.000 người tham dự, tỷ lệ tham gia trung bình 95%."]');
INSERT INTO jobs (id, sort_order, years, period, title, company, company_tip_title, company_tip_body, summary, highlights_json, details_json) VALUES ('job-cntl', 2, '2024–2025', 'Th9/2024 – Th4/2025', 'Social Media Marketing Lead', 'Cơm Niêu Thiên Lý', 'Cơm Niêu Thiên Lý', 'Chuỗi nhà hàng cơm niêu đang mở rộng theo mô hình nhượng quyền.', 'Làm mới nhận diện và vận hành Meta, Zalo, LinkedIn, TikTok cho một chuỗi F&B.', '["Tương tác Facebook tăng 153,4% trong 3 tháng.","Xây brand identity guide mới, chuẩn hóa cửa hàng, social và OOH.","Tăng hơn 10% doanh số cho cửa hàng mới và cửa hàng địa phương."]', '["TikTok thêm 2.000+ người theo dõi, nhiều video đạt 100.000 lượt xem.","Khởi tạo kênh LinkedIn, thu hút 20.000+ người quan tâm nhượng quyền.","Hướng dẫn Content Creator sản xuất, biên tập và đăng tải nội dung.","Quản lý quan hệ KOC/Influencer cho các chiến dịch địa phương."]');
INSERT INTO jobs (id, sort_order, years, period, title, company, company_tip_title, company_tip_body, summary, highlights_json, details_json) VALUES ('job-isna', 3, '2023–2024', 'Th6/2023 – Th3/2024', 'Content Marketing Executive', 'International Schools of North America', 'International Schools of North America', 'Hệ thống trường quốc tế tại TP.HCM; tôi làm việc toàn thời gian tại văn phòng.', 'Vận hành nội dung song ngữ Việt – Anh cho một hệ thống trường quốc tế, từ mạng xã hội đến tuyển sinh.', '["Mỗi tháng: 25–28 bài Facebook, 10 video ngắn Shorts/TikTok, 2 video dài YouTube, 6 bài website 1.000 chữ chuẩn SEO.","3 bài viết SEO lọt Top 10 kết quả tìm kiếm Google.","Nội dung song ngữ cho brochure, leaflet, standee và email marketing gửi phụ huynh."]', '["Lên kế hoạch nội dung song ngữ theo tháng, tuần, ngày và kế hoạch truyền thông cho sự kiện tuyển sinh.","Xây dựng 2 thông điệp truyền thông riêng mỗi tháng cho bài đăng sự kiện và chiến dịch tuyển sinh.","Đề xuất và viết kịch bản video song ngữ về trường, sự kiện, đời sống học sinh, phỏng vấn giáo viên và học sinh.","Theo dõi xu hướng trên mạng xã hội và đề xuất một bài bắt trend mỗi tháng.","Hỗ trợ tổ chức sự kiện nội bộ và sự kiện tuyển sinh tại trường.","Phối hợp với giáo viên nước ngoài và các phòng ban để hoàn thành công việc hiệu quả."]');
INSERT INTO jobs (id, sort_order, years, period, title, company, company_tip_title, company_tip_body, summary, highlights_json, details_json) VALUES ('job-byte', 4, '2022', 'Byte Media Agency', 'Copywriter Lead', 'Byte Media', 'Byte Media Agency', 'Agency truyền thông với khách hàng như Woori Bank, Isuzu Việt Nam, KCN Nam Đình Vũ, Ruco International Clinic.', 'Lên chiến lược nội dung và pitching cho khách hàng lớn ở nhiều ngành.', '["Dẫn dắt mảng video cho Woori Bank: 105.000 follower TikTok, 7.500 tài khoản mới.","45% đề xuất được duyệt trên 15+ dự án pitching.","Kế hoạch đa kênh Facebook, Google, TikTok, LinkedIn cho nhiều thương hiệu."]', '["Xây đề xuất gồm key message, tagline, content pillar, lịch nội dung, bài demo và chi phí.","Viết quảng cáo social, kịch bản, bài SEO, bài PR và định hướng ý tưởng thiết kế.","Phối hợp Account, Media, Sales để đảm bảo cam kết chiến dịch."]');
