INSERT INTO works (id, slug, sort_order, title, kind, description, tone, featured, meta_json) VALUES ('work-bloomsky', 'bloomsky', 0, 'Bloomsky Airways', 'Nhận diện thương hiệu', 'Bộ nhận diện cho một hãng hàng không chuyên bay đến những hòn đảo đẹp nhất Việt Nam. Biểu tượng là chim yến đội nón lá bay ở độ cao an toàn, đại diện cho một hãng bay Việt Nam mến khách, tươi vui và đáng tin cậy.', '#133F52', 1, '{"kicker":"Đồ án nhận diện thương hiệu, Arena Multimedia, 2024","quote":"“To the joyful you and beyond!”","coverKey":"design/bloomsky/cover.webp","coverAlt":"Bìa guidebook Bloomsky Airways: máy bay trên đường băng lúc hoàng hôn","facts":[{"value":"136","label":"trang guidebook","tipTitle":"Guidebook 136 trang","tipBody":"Từ câu chuyện thương hiệu, logo, ấn phẩm văn phòng đến ứng dụng hàng không và truyền thông."},{"value":"5","label":"chương","tipTitle":"5 chương","tipBody":"Giới thiệu, Logo guideline, Ấn phẩm văn phòng, Ứng dụng hàng không, Truyền thông."},{"value":"2","label":"thành viên","tipTitle":"Đồ án nhóm","tipBody":"Lê Thùy Trang và Huỳnh Đan Thanh, giảng viên hướng dẫn: thầy Châu Đức Vũ."}],"swatches":[{"hex":"#133F52","tipTitle":"Xanh chuyên nghiệp","tipBody":"HEX #133F52, R19 G63 B82, C98 M66 Y47 K36"},{"hex":"#FACD66","tipTitle":"Vàng ấm áp","tipBody":"HEX #FACD66, R250 G205 B102, C0 M21 Y79 K0"},{"hex":"#FFFFFF","tipTitle":"Trắng tinh tế","tipBody":"HEX #FFFFFF, R255 G255 B255"}],"fonts":[{"name":"Proxima Nova","italicBold":true,"tipTitle":"Proxima Nova Black Italic","tipBody":"Phông chữ logo: nét nghiêng, trẻ trung, gợi cảm giác năng động và di chuyển nhanh."},{"name":"Gotham","tipTitle":"Gotham Bold và Book","tipBody":"Tiêu đề và nội dung: nét tròn, dễ ứng dụng trong mọi ngữ cảnh."}],"chapters":["Tất cả","Logo guideline","Ấn phẩm văn phòng","Ứng dụng hàng không","Truyền thông"]}');
INSERT INTO work_images (id, work_id, sort_order, chapter, caption, note, media_key, width, height) VALUES ('bl-img-1', 'work-bloomsky', 1, 'Logo guideline', 'Ý nghĩa tên thương hiệu', 'Bloom là sự nở rộ, Sky là bầu trời: một chuyến bay rực rỡ.', 'design/bloomsky/p01.webp', 1600, 900);
