INSERT INTO works (id, slug, sort_order, title, kind, description, tone, featured, meta_json) VALUES ('work-hoa-lo', 'nha-tu-hoa-lo', 1, 'Bộ bưu thiếp “Nhà tù Hỏa Lò – 4 mùa hoa nở”', 'Bưu thiếp', 'Lấy cảm hứng từ những lá thư thời chiến của các chiến sĩ cách mạng bị giam tại di tích Hỏa Lò. Bốn mùa, bốn loài hoa: ban, sen, cúc họa mi, thạch thảo; minh họa bằng AI trên nền giấy cũ.', '#5B4636', 0, '{}');
