INSERT INTO works (id, slug, sort_order, title, kind, description, tone, featured, meta_json) VALUES ('work-cake-bliss', 'cake-bliss', 2, 'Tạp chí Cake Bliss', 'Tạp chí', 'Tạp chí tháng cho người yêu bánh: bánh theo mùa, công thức, chân dung thợ bánh và tiệm bánh đặc biệt. Thiết kế tối giản, hình ảnh sắc nét và hấp dẫn.', '#8A6E57', 0, '{}');
INSERT INTO work_images (id, work_id, sort_order, chapter, caption, note, media_key, width, height) VALUES ('work-cake-bliss-img-1', 'work-cake-bliss', 1, '', 'Tạp chí Cake Bliss', '', 'design/works/cake-bliss.webp', 1198, 798);
INSERT INTO works (id, slug, sort_order, title, kind, description, tone, featured, meta_json) VALUES ('work-com-tuoi', 'com-tuoi-moc-mien', 3, 'Bao bì Cốm tươi Mộc Miên', 'Bao bì', 'Bao bì giúp cốm tươi dễ vận chuyển và phân phối vào siêu thị trong và ngoài nước. Lá sen, hoa sen, bông lúa minh họa bằng AI, kèm ô cửa sổ nhìn thấy hạt cốm.', '#4F5A3E', 0, '{}');
INSERT INTO work_images (id, work_id, sort_order, chapter, caption, note, media_key, width, height) VALUES ('work-com-tuoi-img-1', 'work-com-tuoi', 1, '', 'Bao bì Cốm tươi Mộc Miên', '', 'design/works/com-tuoi-moc-mien.webp', 1202, 796);
INSERT INTO works (id, slug, sort_order, title, kind, description, tone, featured, meta_json) VALUES ('work-dalat-hasfarm', 'dalat-hasfarm', 4, 'Brochure Dalat Hasfarm', 'Brochure', 'Brochure giới thiệu thương hiệu Dalat Hasfarm, đơn vị tiên phong trong trồng hoa chuyên nghiệp tại Việt Nam, với chủ đề “Hoa từ trái tim Việt Nam”.', '#7A4B4B', 0, '{}');
