INSERT INTO projects (id, slug, sort_order, brand, year, tag, card_heading, card_summary, title, subtitle, accent, accent_bg, cover_key, wide, layout, chips_json, wins_json, toc_json, body_json) VALUES ('proj-woori', 'woori', 1, 'Woori Bank', '2022', 'Social & Video', 'Đưa một ngân hàng Hàn Quốc đến gần người trẻ trên TikTok', 'Dẫn dắt mảng video content trong chiến dịch của Woori Bank tại Byte Media, từ concept đến lịch đăng.', 'Woori Bank Z Card: “Đừng chỉ mơ, hãy tự chủ tài chính”', 'Chiến dịch TikTok đưa thẻ ghi nợ Z Card đến Gen Z, biến ước mơ xe sang, túi hiệu thành lời mời mở thẻ online qua e-KYC.', '#1C5BB8', '#DD2F92', 'cases/woori/cover-01.webp', 0, 'case-study', '["Social & Video","TikTok","Gen Z","Byte Media Agency"]', '[{"value":"105K","label":"người theo dõi","tipTitle":"105K người theo dõi","tipBody":"Kênh TikTok xây mới trong 3 tháng."},{"value":"7.500","label":"tài khoản mới","tipTitle":"7.500 tài khoản mới","tipBody":"Đăng ký trên app ngân hàng trong 3 tháng."}]', '[{"id":"tong-quan","label":"Tổng quan"},{"id":"boi-canh","label":"Bối cảnh"},{"id":"muc-tieu","label":"Mục tiêu"},{"id":"insight","label":"Insight"},{"id":"chien-luoc","label":"Chiến lược"},{"id":"y-tuong","label":"Ý tưởng sáng tạo"},{"id":"thuc-thi","label":"Hoạt động thực thi"},{"id":"ket-qua","label":"Kết quả"},{"id":"ket-luan","label":"Kết luận"}]', '{"breadcrumbTitle":"Woori Bank Z Card","cover":{"kind":"triptych","images":[{"mediaKey":"cases/woori/cover-01.webp","alt":"Khung hình key visual Woori Z Card 1"},{"mediaKey":"cases/woori/cover-02.webp","alt":"Khung hình key visual Woori Z Card 2"},{"mediaKey":"cases/woori/cover-03.webp","alt":"Khung hình key visual Woori Z Card 3"}]},"overviewLead":[{"kind":"text","text":"Gen Z muốn tự chủ chi tiêu nhưng thường “cháy túi” vào cuối tháng. Chiến dịch "},{"kind":"bold","text":"“Đừng chỉ mơ, hãy tự chủ tài chính”"},{"kind":"text","text":" đặt thẻ "},{"kind":"abbr","text":"Woori Z Card","tipTitle":"Woori Z Card","tipBody":"Thẻ ghi nợ quốc tế dành cho Gen Z: tích điểm 2% mỗi giao dịch online, tối đa 500.000đ/tháng."},{"kind":"text","text":" vào đúng nơi người trẻ dành thời gian nhiều nhất: TikTok. Mỗi video bắt đầu bằng một ước mơ và kết thúc bằng hành động cụ thể: tải ứng dụng Woori WON, mở tài khoản "},{"kind":"abbr","text":"e-Moi","tipTitle":"Tài khoản e-Moi","tipBody":"Tài khoản thanh toán mở hoàn toàn online trên ứng dụng Woori WON Việt Nam."},{"kind":"text","text":" qua "},{"kind":"abbr","text":"e-KYC","tipTitle":"e-KYC","tipBody":"Định danh khách hàng điện tử: xác thực giấy tờ và khuôn mặt ngay trên điện thoại, không cần ra quầy."},{"kind":"text","text":" và nhận ngay 80.000đ."}],"infoTitle":"Thông tin chiến dịch","infoRows":[{"term":"Thương hiệu","description":"Woori Bank Việt Nam"},{"term":"Sản phẩm","description":"Thẻ ghi nợ quốc tế Woori Z Card, tài khoản e-Moi, ứng dụng Woori WON Việt Nam"},{"term":"Đơn vị thực hiện","description":"Byte Media Agency"},{"term":"Vai trò của tôi","description":"Copywriter Lead, dẫn dắt mảng video content"},{"term":"Thời gian","description":"2022, 3 tháng"},{"term":"Kênh","description":"TikTok, Fanpage, In-app"},{"term":"Đối tượng","description":"Gen Z: học sinh, sinh viên, người mới đi làm"}],"sections":[{"id":"boi-canh","title":"Bối cảnh","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Woori Bank Việt Nam là ngân hàng nước ngoài có vốn điều lệ hàng đầu tại Việt Nam. Năm 2022, ngân hàng muốn mở rộng tệp khách hàng trẻ với thẻ ghi nợ quốc tế Z Card, thiết kế hiện đại và cá tính dành riêng cho Gen Z."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Sản phẩm có nhiều lợi thế: tích điểm 2% mọi giao dịch online (tối đa 500.000đ/tháng), giảm tới 50% tại Woori Store, miễn phí giao dịch, rút tiền ATM ngân hàng khác và duy trì thẻ. Toàn bộ quy trình mở tài khoản và đăng ký thẻ diễn ra online qua e-KYC, kèm ưu đãi 80.000đ vào tài khoản e-Moi."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Thách thức là làm sao để một ngân hàng nước ngoài nói chuyện tự nhiên với Gen Z trên nền tảng video ngắn, và quan trọng hơn, khiến họ thật sự hoàn tất đăng ký trên ứng dụng."}]}]},{"id":"muc-tieu","title":"Mục tiêu","blocks":[{"type":"list","items":[[{"kind":"bold","text":"Chuyển đổi: "},{"kind":"text","text":"đạt 7.500 lượt mở thẻ Z Card thành công qua e-KYC trên ứng dụng Woori WON."}],[{"kind":"bold","text":"Nhận diện: "},{"kind":"text","text":"phủ sóng thương hiệu Woori Bank trên nền tảng video ngắn TikTok."}]]}]},{"id":"insight","title":"Insight","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Gen Z thích tự do thể hiện bản sắc, mua sắm online, đam mê phong cách Hàn Quốc và các xu hướng đang thịnh hành. Họ muốn tự chủ chi tiêu, nhưng lại thường gặp khó khăn khi kiểm soát tài chính cá nhân vào cuối tháng."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Khoảng cách giữa "},{"kind":"bold","text":"điều mình mơ"},{"kind":"text","text":" và "},{"kind":"bold","text":"số dư trong tài khoản"},{"kind":"text","text":" chính là chỗ Z Card có thể bước vào: không bán một chiếc thẻ, mà bán cảm giác lần đầu tự chủ tài chính."}]}]},{"id":"chien-luoc","title":"Chiến lược","blocks":[{"type":"list","items":[[{"kind":"bold","text":"Phễu chuyển đổi ba tầng: "},{"kind":"text","text":"Awareness bằng video animation pop art và KOL; Interest bằng đòn bẩy tài chính 80.000đ và hoàn tiền 2%; Action bằng chuỗi video hướng dẫn 11 bước e-KYC tại nhà."}],[{"kind":"bold","text":"Kể chuyện qua KOL có kiểm soát: "},{"kind":"text","text":"agency trực tiếp viết kịch bản chi tiết bám sát key message, không để KOL tự do sáng tạo lệch thông điệp."}],[{"kind":"bold","text":"CTA ngay từ 3 giây đầu: "},{"kind":"text","text":"intro ngắn kêu gọi follow kênh và nhận 80k để thông điệp không trôi khi người dùng lướt nhanh."}],[{"kind":"bold","text":"Đo lường và điều chỉnh liên tục: "},{"kind":"text","text":"theo dõi lượt nhấp link tải WON App trên bio của influencer, thử nghiệm các bản nhạc trending để tăng hiển thị."}]]}]},{"id":"y-tuong","title":"Ý tưởng sáng tạo","blocks":[{"type":"quote","quote":"“Đừng chỉ mơ, hãy tự chủ tài chính cùng Woori Z Card”","attribution":"Key message: “My first time independent finance”"},{"type":"paragraph","segments":[{"kind":"text","text":"Z Card được định vị là "},{"kind":"bold","text":"chiếc thẻ ngân hàng đầu tiên"},{"kind":"text","text":" đồng hành cùng Gen Z trên hành trình tự chủ tài chính. Biểu tượng xuyên suốt là "},{"kind":"bold","text":"chiếc kính mắt"},{"kind":"text","text":": trong tròng kính lần lượt hiện ra ước mơ như xe sang, túi hiệu, du lịch biển, rồi được thay bằng thẻ Z Card và ứng dụng WON. Ước mơ chuyển thành hiện thực chỉ bằng một lần mở thẻ."}]}]},{"id":"thuc-thi","title":"Hoạt động thực thi","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Chiến dịch triển khai qua ba giai đoạn theo hành trình của người dùng, từ biết đến thương hiệu, hiểu sản phẩm, đến mở thẻ thành công."}]},{"type":"phases","items":[{"kicker":"Giai đoạn 1","title":"Branding & Awareness","description":"“Chiếc thẻ ngân hàng đầu tiên của Gen Z”: video key visual animation và KOL khẳng định phong cách sống tự chủ."},{"kicker":"Giai đoạn 2","title":"Engagement & Education","description":"“Lần đầu tiên tự chủ tài chính và bí kíp tiêu xài hiệu quả”: storytelling từ influencer, minigame nhận thưởng."},{"kicker":"Giai đoạn 3","title":"Conversion & CTA","description":"“Mở thẻ online dễ dàng, nhận ngay 80.000đ”: hướng dẫn 11 bước e-KYC và video thúc đẩy follow kênh."}]},{"type":"stage","id":"gd1","kicker":"Giai đoạn 1","title":"Branding & Awareness","blocks":[{"type":"heading4","text":"Hoạt động 1: Video key visual animation"},{"type":"paragraph","segments":[{"kind":"text","text":"Video 15 đến 30 giây cho TikTok và Fanpage, phong cách pop art 2D/3D trên nền màu thương hiệu. Mở đầu bằng câu hỏi “Ước mơ của bạn là gì?”, hiệu ứng zoom vào tròng kính hiện xe sang và resort biển, rồi Z Card rơi vào tròng kính biến ước mơ thành hiện thực, kết thúc bằng thẻ, ứng dụng WON và phần quà 80.000đ."}]},{"type":"figure","layout":"grid4","aspectRatio":"808 / 1316","images":[{"mediaKey":"cases/woori/storyboard-01.webp","alt":"Khung hình storyboard 1"},{"mediaKey":"cases/woori/storyboard-02.webp","alt":"Khung hình storyboard 2"},{"mediaKey":"cases/woori/storyboard-03.webp","alt":"Khung hình storyboard 3"},{"mediaKey":"cases/woori/storyboard-04.webp","alt":"Khung hình storyboard 4"},{"mediaKey":"cases/woori/storyboard-05.webp","alt":"Khung hình storyboard 5"},{"mediaKey":"cases/woori/storyboard-06.webp","alt":"Khung hình storyboard 6"},{"mediaKey":"cases/woori/storyboard-07.webp","alt":"Khung hình storyboard 7"},{"mediaKey":"cases/woori/storyboard-08.webp","alt":"Khung hình storyboard 8"}],"caption":"Storyboard và voice-over video key visual Z Card: tám khung hình từ ước mơ đến lời kêu gọi mở thẻ.","source":"Byte Media cho Woori Bank"},{"type":"paragraph","segments":[{"kind":"text","text":"Kịch bản phân cảnh do tôi xây dựng, chi tiết đến thời lượng, âm thanh và text trên màn hình:"}]},{"type":"table","headers":["Cảnh","Thời lượng","Âm thanh","Hình ảnh","Text trên màn hình"],"rows":[["1. Mở đầu","3s","Nhạc bump lên","Key visual pop-up, tròng kính còn trống","“Ước mơ của bạn là gì?”"],["2. Xe sang","3s","Nhạc hào hứng, hiệu ứng sao băng","Zoom vào tròng kính có chiếc xe sang","“Lái chiếc xe sang?”"],["3. Du lịch","5s","Hiệu ứng gió","Xe chạy trên đường ven biển, hàng dừa hai bên","“Du lịch sang chảnh”"],["4. Câu hỏi","3s","Rung lắc","Xe trong tròng kính được thay bằng 2 thẻ Woori","“Nhưng tiền đâu để có xe sang?”"],["5. Giải pháp","3s","Swosh, khói","Hai thẻ đặt cạnh nhau, tagline hiện phía trên","“Trong Z Card! Mở tài khoản nhận ngay 80.000đ”"],["6. CTA","3s","CTA","Thẻ đổi tư thế, hiện tagline và logo","“Đừng chỉ mơ, hãy tự chủ tài chính ngay hôm nay”"]]},{"type":"heading4","text":"Hoạt động 2: KOL khẳng định phong cách sống tự chủ"},{"type":"paragraph","segments":[{"kind":"text","text":"Song song với video animation, KOL xuất hiện cùng key visual để gắn Z Card với hình ảnh người trẻ độc lập, tự tin chi tiêu cho đam mê của mình."}]}]},{"type":"stage","id":"gd2","kicker":"Giai đoạn 2","title":"Engagement & Education","blocks":[{"type":"heading4","text":"Hoạt động 1: Storytelling cùng Hoàng Bách"},{"type":"paragraph","segments":[{"kind":"text","text":"Video tình huống Gen Z thực tế với voice-over hài hước, 30 đến 60 giây. Cuối tháng ăn mì tôm ngán ngẩm, đầu tháng có lương lại tiêu xài hoang phí, rồi giật mình vì hóa đơn tiền điện. Lối thoát là bí kíp quản lý chi tiêu với Z Card: tải WON App, mở thẻ nhận ngay 80k và hoàn tiền 2%."}]},{"type":"heading4","text":"Hoạt động 2: Storytelling cùng Như Ngọc"},{"type":"paragraph","segments":[{"kind":"text","text":"Bắt trend đập hộp thẻ và parody phim “Hẹn hò chốn công sở”: từ khoảnh khắc mê chiếc thẻ đen của nam chính đến màn mở hộp thẻ Z Card. Thực tế đời thường: tải WON App mở tài khoản e-Moi nhận 80k, tích điểm online đổi tới 500k, tự tin quẹt thẻ khi mua sắm."}]},{"type":"heading4","text":"Hoạt động 3: Minigame và ưu đãi"},{"type":"paragraph","segments":[{"kind":"text","text":"Minigame nhận thưởng 80k và hoàn tiền 500k giữ nhịp tương tác giữa các video, tạo lý do để người xem quay lại kênh."}]}]},{"type":"stage","id":"gd3","kicker":"Giai đoạn 3","title":"Conversion & CTA","blocks":[{"type":"heading4","text":"Hoạt động 1: Video hướng dẫn 11 bước e-KYC"},{"type":"paragraph","segments":[{"kind":"text","text":"Screen recording kết hợp UI animation và text callout, 18 đến 30 giây: tải WON App, xác thực giấy tờ, chụp khuôn mặt, tạo mật khẩu, chọn địa chỉ nhận thẻ. Mục tiêu là gỡ rào cản cuối cùng trước khi người dùng hành động."}]},{"type":"heading4","text":"Hoạt động 2: Video follow-up và CTA"},{"type":"paragraph","segments":[{"kind":"text","text":"Video 15 đến 20 giây theo concept business và lifestyle: nhân vật bận rộn, sang trọng, tự chủ tài chính nhờ kiểm soát thu chi trên WON App, chỉ tay kêu gọi bấm follow kênh Woori Bank Vietnam."}]},{"type":"heading4","text":"Hoạt động 3: Tối ưu sáng tạo sau feedback"},{"type":"list","items":[[{"kind":"bold","text":"Hình ảnh: "},{"kind":"text","text":"tách nền nhân vật, vẽ lại cửa hàng thời trang, siêu xe, thẻ ngân hàng theo phong cách pop art; đồng nhất nền theo màu thương hiệu; thêm hiệu ứng rung, khói, lấp lánh cho đồ vật."}],[{"kind":"bold","text":"Chữ và chuyển động: "},{"kind":"text","text":"thay khung chữ nhỏ khó đọc bằng text nhảy cỡ lớn cho màn hình 9:16, làm nổi bật “Nhận ngay 80k nhé”; tăng nhịp chuyển cảnh khi zoom vào tròng kính."}],[{"kind":"bold","text":"Quy trình KOL: "},{"kind":"text","text":"tối đa 3 vòng duyệt kịch bản trước khi quay; thêm intro 3 giây kêu gọi follow và nhận 80k."}]]}]}]}],"conclusion":[[{"kind":"text","text":"Chiến dịch Z Card cho thấy một ngân hàng có thể nói chuyện với Gen Z bằng chính ngôn ngữ của họ mà vẫn giữ được mục tiêu kinh doanh rõ ràng. Thay vì liệt kê tính năng, chiến dịch bắt đầu từ ước mơ, dùng một biểu tượng thị giác dễ nhớ là chiếc kính mắt, rồi dẫn người xem qua từng bước tới hành động mở thẻ."}],[{"kind":"text","text":"Điều làm nên kết quả không chỉ là ý tưởng, mà là sự kỷ luật trong thực thi: kịch bản KOL được kiểm soát chặt, CTA đặt ngay 3 giây đầu, và sáng tạo được điều chỉnh liên tục theo feedback. Nhờ đó, cảm hứng được chuyển thành 7.500 tài khoản thật."}]],"nextProjects":[{"slug":"com-nieu-thien-ly","title":"Cơm Niêu Thiên Lý: làm mới nhận diện thương hiệu"},{"slug":"phu-hung-life","title":"Phú Hưng Life: CSR, truyền thông nội bộ và PR lãnh đạo"}]}');
