INSERT INTO projects (id, slug, sort_order, brand, year, tag, card_heading, card_summary, title, subtitle, accent, accent_bg, cover_key, wide, layout, chips_json, wins_json, toc_json, body_json) VALUES ('proj-cntl', 'com-nieu-thien-ly', 2, 'Cơm Niêu Thiên Lý', '2024–2025', 'Brand & Social', 'Làm mới bộ nhận diện và đánh thức mạng xã hội của một chuỗi nhà hàng', 'Xây bộ brand identity guide mới, chuẩn hóa mọi điểm chạm từ cửa hàng đến OOH, và vận hành bốn kênh social.', 'Cơm Niêu Thiên Lý: “Nâng tầm ẩm thực Việt”', 'Làm mới bộ nhận diện cho một chuỗi nhà hàng đang mở rộng, chuẩn hóa mọi điểm chạm và đánh thức bốn kênh mạng xã hội.', '#9A5B2E', '#4A2A1A', 'cases/cntl/cover.webp', 0, 'case-study', '["Brand & Social","F&B","Meta, Zalo, TikTok, LinkedIn","Cửa hàng và OOH"]', '[{"value":"+153,4%","label":"tương tác Facebook","tipTitle":"+153,4% tương tác Facebook","tipBody":"33.800 lượt tương tác sau 3 tháng."},{"value":"+10%","label":"doanh số","tipTitle":"+10% doanh số","tipBody":"Cho cửa hàng mới và cửa hàng địa phương."}]', '[{"id":"tong-quan","label":"Tổng quan"},{"id":"boi-canh","label":"Bối cảnh"},{"id":"muc-tieu","label":"Mục tiêu"},{"id":"insight","label":"Insight"},{"id":"chien-luoc","label":"Chiến lược"},{"id":"y-tuong","label":"Ý tưởng sáng tạo"},{"id":"thuc-thi","label":"Hoạt động thực thi"},{"id":"ket-qua","label":"Kết quả"},{"id":"ket-luan","label":"Kết luận"}]', '{"breadcrumbTitle":"Cơm Niêu Thiên Lý","cover":{"kind":"single","mediaKey":"cases/cntl/cover.webp","alt":"Mâm cơm niêu với hơn 100 món Việt từ nguyên liệu tươi ngon"},"overviewLead":[{"kind":"text","text":"Khi chuỗi nhà hàng mở thêm chi nhánh mới liên tục, hình ảnh thương hiệu trên mạng xã hội lại mỗi bài một kiểu. Tôi cùng đội ngũ nội bộ xác định lại thuộc tính thương hiệu, xây dựng "},{"kind":"bold","text":"bộ hướng dẫn nhận diện mới"},{"kind":"text","text":" và đưa nó vào mọi điểm chạm, từ cửa hàng, "},{"kind":"abbr","text":"OOH","tipTitle":"OOH (Out-of-home)","tipBody":"Quảng cáo ngoài trời: biển hiệu, pano, standee tại cửa hàng."},{"kind":"text","text":" đến Facebook, Zalo, TikTok và LinkedIn. Kết quả: tương tác Facebook tăng 153,4% chỉ sau ba tháng."}],"infoTitle":"Thông tin chiến dịch","infoRows":[{"term":"Thương hiệu","description":"Cơm Niêu Thiên Lý"},{"term":"Ngành","description":"F&B, chuỗi nhà hàng món Việt"},{"term":"Vai trò của tôi","description":"Social Media Marketing Lead"},{"term":"Thời gian","description":"Tháng 9/2024 đến tháng 4/2025"},{"term":"Kênh","description":"Facebook, Zalo, TikTok, LinkedIn, cửa hàng, OOH"},{"term":"Phạm vi","description":"Nhận diện thương hiệu, social, khai trương, chiến dịch theo chủ đề, KOC"}],"sections":[{"id":"boi-canh","title":"Bối cảnh","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Cơm Niêu Thiên Lý là chuỗi nhà hàng món Việt với hơn 10 năm phát triển, đang mở rộng nhanh qua các chi nhánh mới như chi nhánh 30, 31, Quận 5, Phan Đình Giót và hướng tới mô hình nhượng quyền."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/cntl/feed-before-context.webp","alt":"Feed Facebook trước khi làm mới: nền vàng cam rực, mỗi ấn phẩm một bố cục và kiểu chữ khác nhau."}],"caption":"Feed Facebook trước khi làm mới: nền vàng cam rực, mỗi ấn phẩm một bố cục và kiểu chữ khác nhau.","source":"Cơm Niêu Thiên Lý"},{"type":"paragraph","segments":[{"kind":"text","text":"Tốc độ mở rộng đặt ra một vấn đề: hình ảnh thương hiệu chưa thống nhất. Mỗi ấn phẩm dùng màu, bố cục và kiểu chữ khác nhau, khiến khách hàng khó nhận ra một thương hiệu nhất quán giữa cửa hàng, mạng xã hội và quảng cáo ngoài trời. Thương hiệu cũng chưa có kênh tiếp cận riêng cho nhà đầu tư nhượng quyền."}]}]},{"id":"muc-tieu","title":"Mục tiêu","blocks":[{"type":"list","items":[[{"kind":"text","text":"Xác định thuộc tính thương hiệu và xây dựng bộ hướng dẫn nhận diện mới."}],[{"kind":"text","text":"Chuẩn hóa nhận diện trên mọi điểm chạm vật lý và số: cửa hàng, mạng xã hội, OOH."}],[{"kind":"text","text":"Tăng tương tác và lượng người theo dõi trên các kênh mạng xã hội."}],[{"kind":"text","text":"Hỗ trợ doanh số cho cửa hàng mới khai trương và cửa hàng địa phương."}],[{"kind":"text","text":"Mở kênh LinkedIn để tiếp cận nhà đầu tư nhượng quyền."}]]}]},{"id":"insight","title":"Insight","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Thực khách tìm đến cơm niêu không chỉ vì món ăn, mà vì cảm giác được ăn một bữa cơm nhà: hạt cơm cháy giòn trong niêu đất, nồi canh nóng, đĩa cá kho ai cũng nhớ vị. Hình ảnh rực rỡ kiểu khuyến mãi làm lu mờ chính cảm giác ấm áp đó."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Thương hiệu cần trông giống như những gì nó mang lại: "},{"kind":"bold","text":"cơm nhà, ấm áp và tử tế"},{"kind":"text","text":"."}]}]},{"id":"chien-luoc","title":"Chiến lược","blocks":[{"type":"list","items":[[{"kind":"bold","text":"Bắt đầu từ thuộc tính thương hiệu: "},{"kind":"text","text":"cùng đội ngũ nội bộ chốt ba trụ cột Tử tế, Nguyên liệu và Hương vị Việt làm nền cho mọi quyết định hình ảnh và nội dung."}],[{"kind":"bold","text":"Một hệ thống, nhiều điểm chạm: "},{"kind":"text","text":"chuẩn hóa nhận diện từ cửa hàng, social đến OOH để khách hàng gặp cùng một thương hiệu ở mọi nơi."}],[{"kind":"bold","text":"Gắn nhận diện với kinh doanh: "},{"kind":"text","text":"mỗi đợt khai trương, mùa lễ và ưu đãi đều được thiết kế trên cùng hệ thống, vừa giữ chuẩn mực vừa thúc đẩy doanh số."}],[{"kind":"bold","text":"Mở rộng tiếng nói qua KOC và LinkedIn: "},{"kind":"text","text":"KOC lan tỏa trải nghiệm tại địa phương, LinkedIn nói chuyện với nhà đầu tư nhượng quyền."}]]}]},{"id":"y-tuong","title":"Ý tưởng sáng tạo","blocks":[{"type":"quote","quote":"“Nơi vị cơm nhà kết nối những nụ cười”","attribution":"Ba trụ cột: Tử tế · Nguyên liệu · Hương vị Việt"},{"type":"paragraph","segments":[{"kind":"text","text":"Hệ thống hình ảnh mới chuyển từ vàng cam rực sang "},{"kind":"bold","text":"tông nâu đất ấm"},{"kind":"text","text":", món ăn được chụp trên chất liệu mộc như lá chuối, mây tre, niêu đất, kết hợp chữ viết tay mềm mại. Mỗi trụ cột thương hiệu được kể bằng một câu chuyện riêng, đặt trong khung ảnh như tấm thiệp gửi thực khách."}]},{"type":"figure","layout":"grid3","aspectRatio":"1 / 1","images":[{"mediaKey":"cases/cntl/pillar-01.webp","alt":"Trụ cột Tử tế"},{"mediaKey":"cases/cntl/pillar-02.webp","alt":"Trụ cột Nguyên liệu"},{"mediaKey":"cases/cntl/pillar-03.webp","alt":"Trụ cột Hương vị Việt"}],"caption":"Bộ ấn phẩm ba trụ cột thương hiệu: Tử tế, Nguyên liệu, Hương vị Việt.","source":"Cơm Niêu Thiên Lý"}]},{"id":"thuc-thi","title":"Hoạt động thực thi","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Triển khai qua ba giai đoạn: định hình nhận diện, chuẩn hóa điểm chạm và kích hoạt bán hàng."}]},{"type":"phases","items":[{"kicker":"Giai đoạn 1","title":"Định hình nhận diện","description":"Xác định thuộc tính thương hiệu, xây dựng brand identity guide, chuyển đổi feed sang hệ thống mới."},{"kicker":"Giai đoạn 2","title":"Chuẩn hóa điểm chạm","description":"Áp dụng nhận diện trên social, cửa hàng và OOH; hướng dẫn Content Creator sản xuất nội dung."},{"kicker":"Giai đoạn 3","title":"Kích hoạt bán hàng","description":"Truyền thông khai trương, chiến dịch theo mùa, ưu đãi, KOC và kênh LinkedIn cho nhượng quyền."}]},{"type":"stage","id":"gd1","kicker":"Giai đoạn 1","title":"Định hình nhận diện","blocks":[{"type":"heading4","text":"Hoạt động 1: Xây dựng bộ hướng dẫn nhận diện"},{"type":"paragraph","segments":[{"kind":"text","text":"Tôi cùng đội ngũ nội bộ xác định thuộc tính thương hiệu và phát triển bộ brand identity guide mới: bảng màu nâu đất, phong cách ảnh món ăn trên chất liệu mộc, kiểu chữ viết tay kết hợp chữ in đậm, cách đặt logo và thông tin trên từng định dạng."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Bộ nhận diện sau đó được đưa vào thực thi qua các buổi "},{"kind":"bold","text":"photo shooting theo concept"},{"kind":"text","text":" cho từng nhóm món và câu chuyện thương hiệu, cùng với "},{"kind":"bold","text":"sản xuất video"},{"kind":"text","text":" và thiết kế ấn phẩm, để mọi hình ảnh mới đều đi ra từ cùng một chuẩn mực."}]},{"type":"heading4","text":"Hoạt động 2: So sánh trước và sau"},{"type":"beforeAfter","beforeKey":"cases/cntl/ba-before.webp","beforeAlt":"Feed mạng xã hội trước khi làm mới nhận diện","afterKey":"cases/cntl/ba-after.webp","afterAlt":"Feed mạng xã hội sau khi làm mới nhận diện","caption":"Kéo thanh trượt để so sánh feed Facebook trước và sau khi áp dụng bộ nhận diện mới.","source":"Cơm Niêu Thiên Lý"},{"type":"figure","layout":"grid2","aspectRatio":"3 / 2","images":[{"mediaKey":"cases/cntl/stage-before.webp","alt":"Feed trước, giai đoạn khai trương"},{"mediaKey":"cases/cntl/stage-after.webp","alt":"Feed sau khi áp dụng bộ nhận diện"}],"caption":"Hai giai đoạn của feed: trước (trái) và sau (phải) khi chuẩn hóa nhận diện.","source":"Cơm Niêu Thiên Lý"}]},{"type":"stage","id":"gd2","kicker":"Giai đoạn 2","title":"Chuẩn hóa điểm chạm","blocks":[{"type":"heading4","text":"Hoạt động 1: Nội dung mạng xã hội"},{"type":"paragraph","segments":[{"kind":"text","text":"Tôi hướng dẫn Content Creator sản xuất, biên tập và đăng tải nội dung theo chuẩn mới. Mỗi món ăn trở thành một câu chuyện về nguyên liệu và hương vị."}]},{"type":"figure","layout":"grid4","aspectRatio":"4 / 5","images":[{"mediaKey":"cases/cntl/dish-01.webp","alt":"Cơm niêu"},{"mediaKey":"cases/cntl/dish-02.webp","alt":"Cá hú kho thịt ba chỉ"},{"mediaKey":"cases/cntl/dish-03.webp","alt":"Bò xào bí nụ"},{"mediaKey":"cases/cntl/dish-04.webp","alt":"Cơm niêu thủy giòn"}],"caption":"Bộ ảnh món ăn theo phong cách nhận diện mới.","source":"Cơm Niêu Thiên Lý"},{"type":"heading4","text":"Hoạt động 2: Cửa hàng và OOH"},{"type":"paragraph","segments":[{"kind":"text","text":"Nhận diện được chuẩn hóa tại cửa hàng, trên mạng xã hội và quảng cáo ngoài trời, để thực khách gặp cùng một thương hiệu dù ở chi nhánh nào."}]},{"type":"figure","layout":"grid2","aspectRatio":"1 / 1","images":[{"mediaKey":"cases/cntl/branch-q5.webp","alt":"Chào đón chi nhánh Quận 5"},{"mediaKey":"cases/cntl/branch-joy.webp","alt":"Trọn niềm vui cùng thực khách"}],"caption":"Ấn phẩm chào đón chi nhánh mới và trải nghiệm tại nhà hàng.","source":"Cơm Niêu Thiên Lý"},{"type":"heading4","text":"Hoạt động 3: Video thương hiệu 11 năm"},{"type":"video","videoKey":"cases/cntl/video-11-nam.mp4","posterKey":"cases/cntl/video-11-nam-poster.webp","caption":"Video thương hiệu “11 năm Thiên Lý”, 30 giây.","source":"Cơm Niêu Thiên Lý","width":1280,"height":720}]},{"type":"stage","id":"gd3","kicker":"Giai đoạn 3","title":"Kích hoạt bán hàng","blocks":[{"type":"heading4","text":"Hoạt động 1: Truyền thông khai trương chi nhánh mới"},{"type":"paragraph","segments":[{"kind":"text","text":"Mỗi đợt khai trương có chiến lược truyền thông riêng với ưu đãi đủ mạnh để kéo khách đến lần đầu, như cơm niêu cháy giòn 1.000đ mừng chi nhánh 30 hay voucher 50.000đ tại chi nhánh Phan Đình Giót."}]},{"type":"figure","layout":"grid2","aspectRatio":"1 / 1","images":[{"mediaKey":"cases/cntl/opening-cn30.webp","alt":"Cơm niêu cháy giòn 1.000đ mừng khai trương chi nhánh 30"},{"mediaKey":"cases/cntl/opening-pdg.webp","alt":"Mừng khai trương chi nhánh Phan Đình Giót"}],"caption":"Ấn phẩm khai trương chi nhánh.","source":"Cơm Niêu Thiên Lý"},{"type":"heading4","text":"Hoạt động 2: Chiến dịch theo mùa và ưu đãi"},{"type":"paragraph","segments":[{"kind":"text","text":"Các chiến dịch theo chủ đề được lên kế hoạch, chỉ đạo và tối ưu để triển khai đồng bộ trên mọi kênh: bộ sưu tập quà Tết 2025, “Lộc xuân gõ cửa”, ưu đãi món ngon và quà tặng cho thực khách."}]},{"type":"figure","layout":"grid4","aspectRatio":"1 / 1","images":[{"mediaKey":"cases/cntl/tet-01.webp","alt":"Bộ sưu tập Tết 2025"},{"mediaKey":"cases/cntl/tet-02.webp","alt":"Lộc xuân gõ cửa"},{"mediaKey":"cases/cntl/tet-03.webp","alt":"Giảm 20% món ngon thượng hạng"},{"mediaKey":"cases/cntl/tet-04.webp","alt":"Tặng 4 món nước"}],"caption":"Chiến dịch Tết và chương trình ưu đãi.","source":"Cơm Niêu Thiên Lý"},{"type":"heading4","text":"Hoạt động 3: KOC, Influencer và LinkedIn nhượng quyền"},{"type":"paragraph","segments":[{"kind":"text","text":"Tôi quản lý quan hệ với KOC và Influencer, triển khai các chiến dịch nâng uy tín thương hiệu tại thị trường địa phương như workshop nấu ăn cùng khách mời. Song song, kênh LinkedIn được khởi tạo để tiếp cận nhà đầu tư quan tâm đến mô hình nhượng quyền."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/cntl/koc-workshop.webp","alt":"Workshop nấu ăn cùng khách mời và KOC tại nhà hàng."}],"caption":"Workshop nấu ăn cùng khách mời và KOC tại nhà hàng.","source":"Cơm Niêu Thiên Lý"}]}]}],"conclusion":[[{"kind":"text","text":"Dự án cho thấy nhận diện thương hiệu không chỉ là chuyện thẩm mỹ. Khi thương hiệu trông giống như những gì nó mang lại, ấm áp và tử tế như một bữa cơm nhà, mọi nội dung sau đó đều dễ được nhận ra và dễ được yêu thích hơn."}],[{"kind":"text","text":"Bộ nhận diện mới trở thành nền tảng chung cho cả đội ngũ: Content Creator biết phải sản xuất thế nào, mỗi chi nhánh mới khai trương đều mang cùng một gương mặt, và các chiến dịch bán hàng vẫn giữ được chuẩn mực thương hiệu."}]],"nextProjects":[{"slug":"woori","title":"Woori Bank Z Card: tự chủ tài chính cùng Gen Z"},{"slug":"phu-hung-life","title":"Phú Hưng Life: CSR, truyền thông nội bộ và PR lãnh đạo"}]}');
