INSERT INTO project_results (id, project_id, sort_order, value, prefix, suffix, decimals, display_text, label, tip_title, tip_body) VALUES ('res-cntl-2', 'proj-cntl', 2, 2000, '', '+', 0, '2.000+', 'người theo dõi TikTok mới, nhiều video đạt 100.000 lượt xem', 'TikTok', 'Trong 3 tháng đầu triển khai.');
INSERT INTO project_results (id, project_id, sort_order, value, prefix, suffix, decimals, display_text, label, tip_title, tip_body) VALUES ('res-cntl-3', 'proj-cntl', 3, 20000, '', '+', 0, '20.000+', 'người dùng LinkedIn quan tâm đến nhượng quyền', 'Kênh LinkedIn mở mới', 'Tiếp cận nhà đầu tư nhượng quyền.');
INSERT INTO project_results (id, project_id, sort_order, value, prefix, suffix, decimals, display_text, label, tip_title, tip_body) VALUES ('res-cntl-4', 'proj-cntl', 4, 10, '>', '%', 0, '>10%', 'tăng doanh số cho cửa hàng mới và cửa hàng địa phương', 'Truyền thông khai trương', 'Chiến lược cho cửa hàng mới và chiến dịch bán hàng tại địa phương.');
INSERT INTO projects (id, slug, sort_order, brand, year, tag, card_heading, card_summary, title, subtitle, accent, accent_bg, cover_key, wide, layout, chips_json, wins_json, toc_json, body_json) VALUES ('proj-phl', 'phu-hung-life', 3, 'Phú Hưng Life', '2025–2026', 'CSR, PR & Internal Comms', 'PR ra mắt Tổng Giám đốc mới và CSR giáo dục tài chính tại Vĩnh Long', 'Hai dự án nổi bật trong vai trò Senior Content Marketing, cùng các công việc duy trì: truyền thông nội bộ (Beyond the Desk, outing, giải thưởng văn hóa, thư CEO), social post và draft UI website mới.', 'Phú Hưng Life: Senior Content Marketing', 'Hai dự án nổi bật là PR ra mắt Tổng Giám đốc mới và CSR giáo dục tài chính tại Vĩnh Long, cùng các công việc duy trì truyền thông nội bộ, social và website.', '#B08A3E', '#1F2A44', 'cases/phl/cover.webp', 1, 'work-summary', '["Senior Content Marketing","PR báo chí","CSR","Truyền thông nội bộ","Social","Website"]', '[{"value":"10","label":"buổi tập huấn tài chính","tipTitle":"10 buổi tập huấn tài chính","tipBody":"6 tháng tại Vĩnh Long, cùng LSTF và Hội Liên hiệp Phụ nữ tỉnh."},{"value":"1.000+","label":"người tham dự","tipTitle":"1.000+ người tham dự","tipBody":"Tỷ lệ tham gia trung bình 95% qua 10 buổi tập huấn."},{"value":"5","label":"đầu báo","tipTitle":"5 đầu báo","tipBody":"Dân Trí, Tuổi Trẻ, VnExpress, Doanh Nhân Sài Gòn, Vietcetera."}]', '[{"id":"tong-quan","label":"Tổng quan"},{"id":"pr-ceo","label":"PR ra mắt Tổng Giám đốc mới"},{"id":"csr","label":"CSR: Giáo dục tài chính cho phụ nữ Vĩnh Long"},{"id":"noi-bo","label":"Hỗ trợ truyền thông nội bộ"},{"id":"social","label":"Social post"},{"id":"website","label":"Draft UI cho website mới"},{"id":"ket-qua","label":"Kết quả"},{"id":"ket-luan","label":"Kết luận"}]', '{"breadcrumbTitle":"Phú Hưng Life","cover":{"kind":"single","mediaKey":"cases/phl/cover.webp","alt":"Tổng Giám đốc Phú Hưng Life cùng đội ngũ tại sự kiện nội bộ"},"overviewLead":[{"kind":"text","text":"Tại Phú Hưng Life, tôi đảm nhận vai trò "},{"kind":"bold","text":"Senior Content Marketing"},{"kind":"text","text":" cho một doanh nghiệp bảo hiểm nhân thọ có mạng lưới văn phòng trên toàn quốc. Nổi bật nhất là chiến dịch PR ra mắt Tổng Giám đốc mới trên năm đầu báo lớn và chuỗi "},{"kind":"abbr","text":"CSR","tipTitle":"CSR","tipBody":"Trách nhiệm xã hội doanh nghiệp: hoạt động vì cộng đồng, không nhằm bán sản phẩm."},{"kind":"text","text":" giáo dục tài chính cho phụ nữ Vĩnh Long. Song song, tôi duy trì truyền thông nội bộ, nội dung mạng xã hội và tham gia xây dựng website mới."}],"infoTitle":"Thông tin công việc","infoRows":[{"term":"Doanh nghiệp","description":"Phú Hưng Life"},{"term":"Ngành","description":"Bảo hiểm nhân thọ"},{"term":"Vai trò của tôi","description":"Senior Content Marketing"},{"term":"Thời gian","description":"Tháng 4/2025 đến tháng 3/2026"},{"term":"Đối tác","description":"Agency Novaon (PR), Quỹ LSTF và Hội Liên hiệp Phụ nữ tỉnh Vĩnh Long (CSR)"},{"term":"Kênh","description":"Báo chí, sự kiện cộng đồng, Email, GapoWork, Facebook Group nội bộ, fanpage, website"}],"overviewExtraBlocks":[{"type":"phases","autoFit":true,"items":[{"kicker":"Nổi bật","title":"PR ra mắt Tổng Giám đốc","description":"Năm đầu báo lớn, tháng 2/2026.","href":"#pr-ceo"},{"kicker":"Nổi bật","title":"CSR giáo dục tài chính","description":"10 buổi, 1.000+ người tham dự tại Vĩnh Long.","href":"#csr"},{"kicker":"Duy trì","title":"Truyền thông nội bộ","description":"Beyond the Desk, outing, giải thưởng văn hóa, thư CEO.","href":"#noi-bo"},{"kicker":"Duy trì","title":"Social post","description":"Nội dung lifestyle trên fanpage.","href":"#social"},{"kicker":"Duy trì","title":"Draft UI website mới","description":"Trang chủ và trang sản phẩm.","href":"#website"}]}],"sections":[{"id":"pr-ceo","kicker":"Dự án nổi bật","title":"PR ra mắt Tổng Giám đốc mới","tags":["Tháng 2/2026","Phối hợp agency Novaon","5 đầu báo"],"blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Đầu năm 2026, Phú Hưng Life bổ nhiệm Tổng Giám đốc mới, bà Yong Lai Yin. Sự thay đổi lãnh đạo ở một doanh nghiệp bảo hiểm cần được công bố nhất quán để giữ niềm tin của khách hàng, đối tác và đội ngũ tư vấn."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Tôi phối hợp cùng agency Novaon định hướng nội dung, duyệt bài và triển khai chiến dịch PR tích hợp: tin bổ nhiệm trên các báo kinh doanh lớn, kết hợp một bài phỏng vấn editorial trên Vietcetera để kể câu chuyện con người và triết lý lãnh đạo phía sau chức danh."}]},{"type":"quote","quote":"“Trong bảo hiểm, kỷ luật chính là hình thái cao nhất của niềm tin”","attribution":"Bà Yong Lai Yin, Tổng Giám đốc Phú Hưng Life, trả lời phỏng vấn Vietcetera"},{"type":"heading3","text":"Lịch phát hành"},{"type":"table","headers":["Đầu báo","Ngày đăng","Tiêu đề","Vị trí","Lượt xem"],"rows":[["Dân Trí","11/02/2026","Phú Hưng Life bổ nhiệm Tổng giám đốc mới","Top 3 Kinh doanh","16.900"],["Tuổi Trẻ","11/02/2026","Phú Hưng Life củng cố đội ngũ lãnh đạo cho giai đoạn tăng trưởng mới","Link 3 Doanh nghiệp","4.056"],["VnExpress","13/02/2026","Phú Hưng Life bổ nhiệm Tổng giám đốc mới","Top 6 Kinh doanh","6.126"],["Doanh Nhân Sài Gòn","25/02/2026","Tân Tổng giám đốc và chiến lược phát triển bền vững Phú Hưng Life","Chuyên mục Nổi bật","4.687"],["Vietcetera","26/02/2026","Bà Yong Lai Yin: “Trong bảo hiểm, kỷ luật chính là hình thái cao nhất của niềm tin”","Nổi bật trang chủ","Bài editorial"]]},{"type":"figure","layout":"grid2","aspectRatio":"1400 / 840","images":[{"mediaKey":"cases/phl/press-dantri.webp","alt":"Bài đăng trên Dân Trí"},{"mediaKey":"cases/phl/press-vnexpress.webp","alt":"Bài đăng trên VnExpress"},{"mediaKey":"cases/phl/press-tuoitre.webp","alt":"Bài đăng trên Tuổi Trẻ"},{"mediaKey":"cases/phl/press-dnsg.webp","alt":"Bài đăng trên Doanh Nhân Sài Gòn"}],"caption":"Vị trí bài viết trên trang chủ và trang chuyên mục của các đầu báo.","source":"Báo cáo chiến dịch PR, Novaon"},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/phl/press-vietcetera.webp","alt":"Bài phỏng vấn trên Vietcetera, vị trí nổi bật chuyên mục Kinh doanh."}],"caption":"Bài phỏng vấn trên Vietcetera, vị trí nổi bật chuyên mục Kinh doanh.","source":"Báo cáo chiến dịch PR, Novaon"}]},{"id":"csr","kicker":"Dự án nổi bật","title":"CSR: Giáo dục tài chính cho phụ nữ Vĩnh Long","tags":["Tháng 4 đến 9/2025","LSTF","Hội Liên hiệp Phụ nữ tỉnh Vĩnh Long"],"blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Với nhiều phụ nữ ở nông thôn, kiến thức tài chính cá nhân vẫn còn xa lạ. Phú Hưng Life cùng Quỹ Hỗ trợ Cộng đồng Đinh Thiện Lý (LSTF) và Hội Liên hiệp Phụ nữ tỉnh Vĩnh Long tổ chức hành trình tập huấn giáo dục tài chính kéo dài 6 tháng."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Chương trình gồm 10 buổi tập huấn tại nhiều xã trong tỉnh, thu hút hơn 1.000 người tham dự với tỷ lệ tham gia trung bình 95%, khép lại bằng hai buổi cuối ngày 25 và 26/09/2025 tại phường Phú Khương và xã Bình Đại."}]},{"type":"paragraph","segments":[{"kind":"text","text":"Tôi tham gia đồng tổ chức chương trình, sản xuất ấn phẩm thiết kế và nội dung truyền thông, đảm bảo nhận diện tại sự kiện thống nhất với brand guideline toàn quốc, và truyền thông kết quả trên fanpage chính thức. "},{"kind":"link","text":"Xem bài đăng trên Facebook","href":"https://www.facebook.com/PhuHungLifeOfficial/posts/pfbid0nAxLZg5wvyS133RqexhddxnBWcSoSeekWzTeSZW1a99u4LUvKqm1DjgwYSW63TfMl"},{"kind":"text","text":"."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/phl/csr-vinh-long.webp","alt":"Các buổi tập huấn giáo dục tài chính cho phụ nữ tại Vĩnh Long, 2025."}],"caption":"Các buổi tập huấn giáo dục tài chính cho phụ nữ tại Vĩnh Long, 2025.","source":"Fanpage Phú Hưng Life"}]},{"id":"noi-bo","kicker":"Công việc duy trì","title":"Hỗ trợ truyền thông nội bộ","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Bên cạnh hai dự án nổi bật, tôi duy trì và hỗ trợ các hoạt động truyền thông trong hệ sinh thái nội bộ (Email, GapoWork, Facebook Group), dùng concept bắt trend để tăng gắn kết nhân viên mà vẫn giữ đúng chuẩn thương hiệu."}]},{"type":"heading3","text":"Beyond the Desk"},{"type":"paragraph","segments":[{"kind":"text","text":"Chuyên mục giới thiệu đồng nghiệp “phía sau bàn làm việc”. Mỗi kỳ là một bộ post hỏi đáp vui về phong cách làm việc, sở thích độc lạ, hoạt động nghỉ trưa hay cách đối mặt với những task “khó nhằn”. Tôi thiết kế toàn bộ bộ post theo phong cách minh họa chibi trên nền vàng, giúp nhân viên ở các phòng ban hiểu nhau hơn."}]},{"type":"figure","layout":"grid3","aspectRatio":"1 / 1","images":[{"mediaKey":"cases/phl/btd-01.webp","alt":"Beyond the Desk, post 1"},{"mediaKey":"cases/phl/btd-02.webp","alt":"Beyond the Desk, post 2"},{"mediaKey":"cases/phl/btd-03.webp","alt":"Beyond the Desk, post 3"},{"mediaKey":"cases/phl/btd-04.webp","alt":"Beyond the Desk, post 4"},{"mediaKey":"cases/phl/btd-05.webp","alt":"Beyond the Desk, post 5"},{"mediaKey":"cases/phl/btd-06.webp","alt":"Beyond the Desk, post 6"}],"caption":"Bộ post Beyond the Desk do tôi thiết kế.","source":"Phú Hưng Life"},{"type":"heading3","text":"Outing 2025 “Ride the Waves”"},{"type":"paragraph","segments":[{"kind":"text","text":"Thiết kế key visual và poster lịch trình cho chuyến outing công ty từ ngày 12 đến 14/09/2025."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/phl/outing-2025.webp","alt":"Poster lịch trình Outing 2025 “Ride the Waves”."}],"caption":"Poster lịch trình Outing 2025 “Ride the Waves”.","source":"Phú Hưng Life"},{"type":"heading3","text":"Culture Ambassador Award"},{"type":"paragraph","segments":[{"kind":"text","text":"Thiết kế cúp và ấn phẩm vinh danh cho giải Culture Ambassador Award, ghi nhận nhân viên lan tỏa giá trị cốt lõi của doanh nghiệp."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/phl/caa-trophy.webp","alt":"Mockup cúp Culture Ambassador Award 2025."}],"caption":"Mockup cúp Culture Ambassador Award 2025.","source":"Phú Hưng Life"},{"type":"heading3","text":"Thư Tổng Giám đốc hằng tháng"},{"type":"paragraph","segments":[{"kind":"text","text":"Chấp bút và thiết kế thông điệp Tổng Giám đốc gửi toàn thể nhân viên mỗi tháng, song ngữ Việt và Anh."}]},{"type":"figure","layout":"grid2","aspectRatio":"99 / 140","images":[{"mediaKey":"cases/phl/ceo-msg-vi.webp","alt":"Thông điệp Tổng Giám đốc tháng 12/2025, tiếng Việt"},{"mediaKey":"cases/phl/ceo-msg-en.webp","alt":"General Director Message, December 2025"}],"caption":"Thông điệp Tổng Giám đốc tháng 12/2025, bản tiếng Việt và tiếng Anh.","source":"Phú Hưng Life"}]},{"id":"social","kicker":"Công việc duy trì","title":"Social post","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Tôi phụ trách nội dung cho fanpage Phú Hưng Life, trong đó có chuỗi bài lifestyle gần gũi với đời sống để thương hiệu bảo hiểm hiện diện tự nhiên hơn trong mùa lễ cuối năm. Mỗi bài gồm phần viết và bộ hình ảnh đồng bộ nhận diện."}]},{"type":"list","items":[[{"kind":"bold","text":"26/12: "},{"kind":"text","text":"“Mùa tiệc tùng rộn ràng, đừng để hệ tiêu hóa ‘lên tiếng’”, gợi ý 3 loại nước uống giúp “giải cứu” hệ tiêu hóa."}],[{"kind":"bold","text":"31/12: "},{"kind":"text","text":"“Không chỉ 12 trái nho, thêm món đậu lăng để may mắn gấp đôi!”, kể về phong tục đón năm mới ở Tây Ban Nha và Ý."}]]},{"type":"tallPair","columns":"minmax(0, 1fr) minmax(0, 1.44fr)","items":[{"mediaKey":"cases/phl/social-2612.webp","alt":"Bộ hình bài lifestyle ngày 26/12","caption":"Lifestyle post 26/12.","source":"Phú Hưng Life"},{"mediaKey":"cases/phl/social-3112.webp","alt":"Bộ hình bài lifestyle ngày 31/12","caption":"Lifestyle post 31/12.","source":"Phú Hưng Life"}]}]},{"id":"website","kicker":"Công việc duy trì","title":"Draft UI cho website mới","blocks":[{"type":"paragraph","segments":[{"kind":"text","text":"Tôi tham gia xây dựng bản draft UI cho website mới của Phú Hưng Life, tập trung vào hành trình của khách hàng: tìm mục tiêu bảo vệ phù hợp, giải quyết quyền lợi, thanh toán phí, đọc tin tức và blog, rồi để lại thông tin tư vấn. Giao diện dùng màu vàng thương hiệu, bố cục thoáng và nút kêu gọi hành động rõ ràng."}]},{"type":"figure","layout":"single","images":[{"mediaKey":"cases/phl/web-hero.webp","alt":"Trang chủ: ô tìm kiếm “Mục tiêu bảo vệ của bạn là gì?” ngay màn hình đầu."}],"caption":"Trang chủ: ô tìm kiếm “Mục tiêu bảo vệ của bạn là gì?” ngay màn hình đầu.","source":"Phú Hưng Life"},{"type":"tallPair","items":[{"mediaKey":"cases/phl/web-home-full.webp","alt":"Toàn bộ trang chủ website mới","caption":"Toàn bộ trang chủ.","source":"Phú Hưng Life"},{"mediaKey":"cases/phl/web-product-full.webp","alt":"Toàn bộ trang sản phẩm website mới","caption":"Toàn bộ trang sản phẩm.","source":"Phú Hưng Life"}]},{"type":"figure","layout":"grid2","aspectRatio":"3 / 2","images":[{"mediaKey":"cases/phl/web-claims.webp","alt":"Khối giải quyết quyền lợi và thanh toán phí"},{"mediaKey":"cases/phl/web-health.webp","alt":"Trang sản phẩm: kế hoạch bảo vệ sức khỏe"}],"caption":"Chi tiết các khối nội dung trên trang chủ và trang sản phẩm.","source":"Phú Hưng Life"}]}],"resultsNote":"Trong cùng giai đoạn, tương tác tổng trên Website, Facebook, LinkedIn và TikTok của Phú Hưng Life tăng 30%, và 100% văn phòng toàn quốc tuân thủ brand guideline.","conclusion":[[{"kind":"text","text":"Ở Phú Hưng Life, công việc truyền thông trải dài từ những dự án lớn có độ phủ báo chí đến những việc nhỏ mỗi tuần như một bộ post nội bộ hay một bài lifestyle. Điểm chung là sự nhất quán: cùng một giọng nói thương hiệu, cùng một chuẩn nhận diện, để niềm tin được xây dần qua từng điểm chạm."}]],"nextProjects":[{"slug":"woori","title":"Woori Bank Z Card: tự chủ tài chính cùng Gen Z"},{"slug":"com-nieu-thien-ly","title":"Cơm Niêu Thiên Lý: Nâng tầm ẩm thực Việt"}]}');
