INSERT INTO project_results (id, project_id, sort_order, value, prefix, suffix, decimals, display_text, label, tip_title, tip_body) VALUES ('res-phl-4', 'proj-phl', 4, 1000, '', '+', 0, '1.000+', 'người tham dự, tỷ lệ tham gia trung bình 95%', 'CSR Vĩnh Long 2025', 'Hơn 1.000 người tham dự qua 10 buổi tập huấn, tỷ lệ tham gia trung bình 95%.');
